script:
const root = root_element;
const setText = (field, value) => {
  root.querySelectorAll(`[data-field="${field}"]`).forEach((el) => {
    el.textContent = value;
  });
};

const render = (d) => {
  setText("present_today", d.present_today ?? 0);
  setText("active_employees", d.active_employees ?? 0);
  setText("presence_rate", d.presence_rate ?? 0);
  setText("complete_today", d.complete_today ?? 0);
  setText("complete_rate", d.complete_rate ?? 0);
  setText("avg_hours", Number(d.avg_hours || 0).toFixed(2));
  setText("still_in", d.still_in ?? 0);
  setText("check_ins_today", d.check_ins_today ?? 0);
  setText("check_outs_today", d.check_outs_today ?? 0);
  setText("punches_today", d.punches_today ?? 0);
  setText("punches_week", d.punches_week ?? 0);

  const presenceMeter = root.querySelector('[data-meter="presence_rate"]');
  if (presenceMeter) {
    presenceMeter.style.width = Math.min(100, Number(d.presence_rate || 0)) + "%";
  }
  const hoursMeter = root.querySelector('[data-meter="avg_hours"]');
  if (hoursMeter) {
    hoursMeter.style.width = Math.min(100, (Number(d.avg_hours || 0) / 10) * 100) + "%";
  }
  const ring = root.querySelector('[data-ring="complete_rate"]');
  if (ring) {
    ring.style.setProperty("--p", Number(d.complete_rate || 0));
  }

  const bars = root.querySelector("[data-bars]");
  if (!bars) return;
  bars.innerHTML = "";
  const max = Math.max(1, Number(d.max_week || 0));
  const labels = d.week_labels || [];
  const ins = d.week_ins || [];
  const outs = d.week_outs || [];
  const totals = d.week_totals || [];
  labels.forEach((label, i) => {
    const total = Number(totals[i] || 0);
    const inH = (Number(ins[i] || 0) / max) * 100;
    const outH = (Number(outs[i] || 0) / max) * 100;
    const day = document.createElement("div");
    day.className = "etp-kpi__day";
    day.innerHTML = `
      <div class="etp-kpi__day-val">${total}</div>
      <div class="etp-kpi__stack">
        <div class="etp-kpi__seg etp-kpi__seg--in" style="height:${inH}%"></div>
        <div class="etp-kpi__seg etp-kpi__seg--out" style="height:${outH}%"></div>
      </div>
      <div class="etp-kpi__day-label">${frappe.utils.escape_html(label)}</div>
    `;
    bars.appendChild(day);
  });
};

frappe.call({
  method: "easytimepro.easy_timepro.analytics.get_workspace_kpis",
  callback(r) {
    if (r.message) {
      render(r.message);
    }
  },
});

style:
.etp-kpi { font-family: inherit; color: #101828; }
.etp-kpi__grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 14px;
}
.etp-kpi__card {
  position: relative;
  border-radius: 14px;
  border: 1px solid #e4e7ec;
  background: #ffffff;
  box-shadow: 0 1px 2px rgba(16,24,40,0.04), 0 8px 20px rgba(16,24,40,0.04);
  padding: 16px 16px 14px;
  overflow: hidden;
  min-height: 132px;
}
.etp-kpi__card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: #1f4b99;
}
.etp-kpi__card--navy::before { background: #1f4b99; }
.etp-kpi__card--green::before { background: #12b76a; }
.etp-kpi__card--blue::before { background: #2e90fa; }
.etp-kpi__card--amber::before { background: #f79009; }
.etp-kpi__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
}
.etp-kpi__label {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #667085;
}
.etp-kpi__icon {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: linear-gradient(135deg, #eff4ff, #d1e0ff);
  border: 1px solid #b2ccff;
}
.etp-kpi__chip {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: 999px;
  background: #eff4ff;
  color: #175cd3;
  border: 1px solid #b2ccff;
}
.etp-kpi__chip--warn {
  background: #fffaeb;
  color: #b54708;
  border-color: #fedf89;
}
.etp-kpi__value {
  font-size: 30px;
  font-weight: 750;
  letter-spacing: -0.03em;
  line-height: 1.1;
  color: #101828;
  font-variant-numeric: tabular-nums;
}
.etp-kpi__value small {
  font-size: 14px;
  font-weight: 650;
  margin-left: 2px;
  color: #667085;
}
.etp-kpi__sub {
  margin-top: 6px;
  font-size: 12px;
  color: #667085;
}
.etp-kpi__meter {
  margin-top: 12px;
  height: 6px;
  border-radius: 99px;
  background: #eef2f6;
  overflow: hidden;
}
.etp-kpi__meter > span {
  display: block;
  height: 100%;
  width: 0;
  border-radius: 99px;
  background: linear-gradient(90deg, #1f4b99, #2e90fa);
  transition: width 0.6s ease;
}
.etp-kpi__card--green .etp-kpi__meter > span,
.etp-kpi__card--blue .etp-kpi__meter > span { background: linear-gradient(90deg, #12b76a, #32d583); }
.etp-kpi__card--blue .etp-kpi__meter > span { background: linear-gradient(90deg, #2e90fa, #53b1fd); }
.etp-kpi__ring {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 10px;
  font-weight: 750;
  color: #067647;
  background:
    radial-gradient(closest-side, #fff 72%, transparent 73% 100%),
    conic-gradient(#12b76a calc(var(--p, 0) * 1%), #e4e7ec 0);
}
.etp-kpi__trend {
  border-radius: 14px;
  border: 1px solid #e4e7ec;
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  box-shadow: 0 1px 2px rgba(16,24,40,0.04), 0 8px 20px rgba(16,24,40,0.04);
  padding: 16px 18px 14px;
}
.etp-kpi__trend-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}
.etp-kpi__trend-title {
  font-size: 14px;
  font-weight: 700;
  color: #101828;
}
.etp-kpi__trend-sub {
  font-size: 12px;
  color: #667085;
  margin-top: 2px;
}
.etp-kpi__legend {
  display: flex;
  gap: 12px;
  font-size: 11px;
  color: #475467;
  font-weight: 600;
}
.etp-kpi__legend-item { display: inline-flex; align-items: center; gap: 6px; }
.etp-kpi__swatch {
  width: 8px;
  height: 8px;
  border-radius: 2px;
  display: inline-block;
}
.etp-kpi__swatch--in { background: #1f4b99; }
.etp-kpi__swatch--out { background: #b42318; }
.etp-kpi__bars {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 10px;
  align-items: end;
  min-height: 140px;
}
.etp-kpi__day {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.etp-kpi__stack {
  width: 100%;
  max-width: 36px;
  height: 110px;
  border-radius: 8px 8px 4px 4px;
  background: #eef2f6;
  display: flex;
  flex-direction: column-reverse;
  overflow: hidden;
  position: relative;
}
.etp-kpi__seg {
  width: 100%;
  transition: height 0.55s ease;
}
.etp-kpi__seg--in { background: linear-gradient(180deg, #2e90fa, #1f4b99); }
.etp-kpi__seg--out { background: linear-gradient(180deg, #f97066, #b42318); }
.etp-kpi__day-label {
  font-size: 11px;
  font-weight: 600;
  color: #667085;
}
.etp-kpi__day-val {
  font-size: 11px;
  font-weight: 700;
  color: #344054;
  font-variant-numeric: tabular-nums;
}
@media (max-width: 1100px) {
  .etp-kpi__grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 640px) {
  .etp-kpi__grid { grid-template-columns: 1fr; }
  .etp-kpi__bars { gap: 6px; }
}
